"""Genera pagine HTML statiche da dati locali. Nessuna dipendenza esterna."""
from pathlib import Path
from html import escape as e
from collections import Counter
import json
ROOT=Path(__file__).resolve().parents[1]
DATA=json.loads((ROOT/'data/catalog.json').read_text())
DIMS=json.loads((ROOT/'data/image-dimensions.json').read_text())
CATS={c['id']:c for c in DATA['categories']};COUNTS=Counter(p['category'] for p in DATA['products'])
ARROW='<span aria-hidden="true">↗</span>'
SEARCH='<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg>'

def image(path,alt,base='',cls='',lazy=True):
    d=DIMS.get(path,{'width':600,'height':400})
    return f'<img class="{cls}" src="{base}{e(path)}" alt="{e(alt)}" width="{d["width"]}" height="{d["height"]}" '+('loading="lazy" ' if lazy else '')+'decoding="async"/>'

def client_catalog(value):
    # La provenienza resta nei file sorgente; il browser riceve solo dati locali.
    if isinstance(value, dict):
        return {k: client_catalog(v) for k, v in value.items() if k not in {'source', 'sourceUrl'}}
    if isinstance(value, list):
        return [client_catalog(v) for v in value]
    return value

