def page(title,description,body,base='',active='',bodyclass='',extra=''):
    return f'''<!doctype html><html lang="it"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width, initial-scale=1"/><meta name="theme-color" content="#080808"/><meta name="description" content="{e(description)}"/><title>{e(title)} | Marmi360</title><link rel="icon" type="image/svg+xml" href="{base}assets/favicon.svg"/><link rel="preload" href="{base}assets/fonts/instrument-sans-latin-600-normal.woff2" as="font" type="font/woff2" crossorigin/><link rel="stylesheet" href="{base}assets/styles.css?v=marmi360-17"/><meta property="og:title" content="{e(title)} | Marmi360"/><meta property="og:description" content="{e(description)}"/>{extra}</head><body class="{bodyclass}" data-base="{base}">{header(base,active)}<main id="main">{body}</main>{footer(base)}<script src="{base}assets/catalog.js?v=marmi360-17" defer></script><script src="{base}assets/app.js?v=marmi360-17" defer></script></body></html>'''

def card(p,base=''):
    cat=CATS[p['category']]
    return f'''<article class="product-card"><a href="{base}prodotti/{e(p['slug'])}.html" class="product-open"><div class="product-photo">{image(p['image'],p['name'],base)}<span class="card-arrow" aria-hidden="true">↗</span></div><div class="product-meta"><span>{e(cat['name'])}</span><h3>{e(p['name'])}</h3><p>{str(len(p.get('variants',[])))+' varianti documentate' if p.get('variants') else 'Consulta i dati del prodotto'}</p></div></a><button class="quick-add" type="button" data-add="{e(p['id'])}" aria-label="Aggiungi {e(p['name'])} alla richiesta">＋<span>Aggiungi alla richiesta</span></button></article>'''

